.ds-control{font-family:"Noto Sans JP", sans-serif;cursor:pointer;transition:background .18s,color .18s,border-color .18s}.ds-control:disabled{cursor:not-allowed;opacity:.5}.ds-control:focus-visible{outline:3px solid #8ab49b;outline-offset:4px}@media(prefers-reduced-motion:reduce){.ds-control{transition:none!important;scroll-behavior:auto!important}}.ds-stay-panel {
  background: var(--green, #1b4b3e);
  color: white;
