  padding: 28px 30px;
  display: flex;
  position: relative;
  overflow: hidden;
  min-height: 227px;
  align-items: center;
}
.ds-stay-panel > div:first-child {
  position: relative;
  z-index: 1;
}
.ds-stay-status {
  font-size: 0.75rem;
  color: #d3e1d7;
  display: flex;
  gap: 7px;
  align-items: center;
  margin-bottom: 13px;
}
.ds-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #cedbc7;
}
.ds-stay-panel h2 {
  font-size: 1.3rem;
  line-height: 1.7;
  margin-bottom: 5px;
  font-weight: 500;
  letter-spacing: 0.025em;
}
.ds-stay-panel p {
  color: #d7e4da;
  font-size: 0.8rem;
  margin-bottom: 20px;
}
.ds-stay-motif {
  position: absolute;
  right: 14px;
  top: 39px;
  width: 150px;
  height: 150px;
  color: #c3d6bd;
  opacity: 0.45;
  display: flex;
  justify-content: center;
  align-items: center;
}
.ds-stay-motif span {
  width: 90px;
  height: 130px;
  border: 1px solid #d4e4ca;
  border-radius: 50%;
  position: absolute;
  transform: rotate(35deg);
}
.ds-stay-motif span:nth-child(2) {
  transform: rotate(-35deg);
}
.ds-stay-motif svg {
  width: 32px;
}
